package br.com.sussmartcare.queue.application; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; @Component public class WaitTimeEstimator {private final int averageMinutes;private final int parallelCapacity;public WaitTimeEstimator(@Value("${queue.estimate.average-service-minutes:12}")int avg,@Value("${queue.estimate.parallel-capacity:1}")int cap){averageMinutes=Math.max(1,avg);parallelCapacity=Math.max(1,cap);}public int estimateMinutes(int position){return (int)Math.ceil((double)Math.max(1,position)/parallelCapacity)*averageMinutes;}public FacilityEstimate aggregate(int waiting){int central=waiting==0?0:estimateMinutes(waiting);int min=(int)Math.floor(central*0.8);int max=(int)Math.ceil(central*1.2);String load=waiting<5?"LOW":waiting<15?"MEDIUM":"HIGH";return new FacilityEstimate(waiting,min,max,load,averageMinutes,parallelCapacity);}public record FacilityEstimate(int waitingPatients,int estimatedMinMinutes,int estimatedMaxMinutes,String loadLevel,int assumedAverageServiceMinutes,int assumedParallelCapacity){}}